(function () {
  "use strict";

  // ── Absorbance model: Catmull-Rom spline through hand-tuned anchor points ──
  var CP = [
    [200, 0.34], [205, 0.55], [210, 0.78], [214, 0.85], [217, 0.87],
    [220, 0.84], [225, 0.62], [230, 0.35], [235, 0.16], [240, 0.09],
    [250, 0.06], [260, 0.055], [280, 0.05], [300, 0.045], [320, 0.04],
    [340, 0.037], [360, 0.034], [380, 0.031], [400, 0.028]
  ];
  function cr(x) {
    var P = CP, n = P.length;
    if (x <= P[0][0]) return P[0][1];
    if (x >= P[n - 1][0]) return P[n - 1][1];
    var i = 0;
    while (i < n - 2 && x > P[i + 1][0]) i++;
    var p0 = P[Math.max(0, i - 1)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(n - 1, i + 2)];
    var t = (x - p1[0]) / (p2[0] - p1[0]), t2 = t * t, t3 = t2 * t;
    return 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
