  "use strict";

  // ── Absorbance model: Catmull-Rom spline through hand-tuned anchor points ──
  var CP = [
    [200, 0.34], [205, 0.55], [210, 0.78], [214, 0.85], [217, 0.87],
    [220, 0.84], [225, 0.62], [230, 0.35], [235, 0.16], [240, 0.09],
    [250, 0.06], [260, 0.055], [280, 0.05], [300, 0.045], [320, 0.04],
    [340, 0.037], [360, 0.034], [380, 0.031], [400, 0.028]
  ];
  function cr(x) {
    var P = CP, n = P.length;
    if (x <= P[0][0]) return P[0][1];
    if (x >= P[n - 1][0]) return P[n - 1][1];
    var i = 0;
    while (i < n - 2 && x > P[i + 1][0]) i++;
    var p0 = P[Math.max(0, i - 1)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(n - 1, i + 2)];
    var t = (x - p1[0]) / (p2[0] - p1[0]), t2 = t * t, t3 = t2 * t;
    return 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
  }

  var curvePts = [];
  for (var w = 200; w <= 400; w += 1) curvePts.push({ x: w, y: cr(w) });

  var MAGENTA = "#d6006e";
  var state = { wl: 217, cur: cr(217), region: "none" };

  // ── Canvas mount ──
  var canvas = document.createElement("canvas");
  canvas.style.cssText = "width:100%;height:100%;display:block";
  document.getElementById("container").appendChild(canvas);

  function arrow(ctx, x1, y1, x2, y2, color, lw) {
    ctx.save();
    ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = lw || 2;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
    var a = Math.atan2(y2 - y1, x2 - x1), h = 7;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - h * Math.cos(a - 0.42), y2 - h * Math.sin(a - 0.42));
    ctx.lineTo(x2 - h * Math.cos(a + 0.42), y2 - h * Math.sin(a + 0.42));
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }
  function haloText(ctx, txt, x, y, font, color, align) {
    ctx.save();
    ctx.font = font; ctx.textBaseline = "alphabetic";
    ctx.textAlign = align || "left";
    ctx.lineWidth = 3; ctx.strokeStyle = "rgba(255,255,255,0.92)"; ctx.lineJoin = "round";
    ctx.strokeText(txt, x, y);
    ctx.fillStyle = color; ctx.fillText(txt, x, y);
    ctx.restore();
  }

  var figurePlugin = {
    id: "figureDecor",
    beforeDraw: function (chart) {
      var ca = chart.chartArea; if (!ca) return;
      var ctx = chart.ctx;
      // uniform pink→white vertical gradient (deeper pink at top), full width
      var g = ctx.createLinearGradient(0, ca.top, 0, ca.bottom);
      g.addColorStop(0, "rgba(246,206,221,0.95)");
      g.addColorStop(0.55, "rgba(250,228,236,0.55)");
      g.addColorStop(1, "rgba(255,255,255,0.10)");
      ctx.save(); ctx.fillStyle = g;
      ctx.fillRect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);
      ctx.restore();
    },
    beforeDatasetsDraw: function (chart) {
      var ca = chart.chartArea; if (!ca) return;
      if (state.region === "none") return; // default = clean source view, no shading
      var ctx = chart.ctx, xs = chart.scales.x;
      var xb = xs.getPixelForValue(250);
      var peak = state.region === "peak";
      ctx.save();
      // dim the non-emphasized side with a soft white veil
      ctx.fillStyle = "rgba(255,255,255,0.5)";
      if (peak) ctx.fillRect(xb, ca.top, ca.right - xb, ca.bottom - ca.top);
      else ctx.fillRect(ca.left, ca.top, xb - ca.left, ca.bottom - ca.top);
      // tint the emphasized side
      ctx.fillStyle = "rgba(214,0,110,0.13)";
      if (peak) ctx.fillRect(ca.left, ca.top, xb - ca.left, ca.bottom - ca.top);
      else ctx.fillRect(xb, ca.top, ca.right - xb, ca.bottom - ca.top);
      ctx.restore();
    },
    afterDatasetsDraw: function (chart) {
      var ca = chart.chartArea; if (!ca) return;
      var ctx = chart.ctx, xs = chart.scales.x, ys = chart.scales.y;

      // λ_max annotation: fixed above-RIGHT of the crest (matches source placement)
      var px = xs.getPixelForValue(217), py = ys.getPixelForValue(cr(217));
      var ax = px + 30, ay = py - 10;
      if (ax > ca.right - 120) ax = ca.right - 120;
      ctx.save();
      ctx.textBaseline = "alphabetic"; ctx.textAlign = "left";
      ctx.lineWidth = 3; ctx.strokeStyle = "rgba(255,255,255,0.92)"; ctx.lineJoin = "round";
      ctx.fillStyle = "#111";
      ctx.font = "italic 15px Georgia, serif";
      ctx.strokeText("λ", ax, ay); ctx.fillText("λ", ax, ay);
      var wL = ctx.measureText("λ").width;
      ctx.font = "italic 10px Georgia, serif";
      ctx.strokeText("max", ax + wL, ay + 4); ctx.fillText("max", ax + wL, ay + 4);
      var wM = ctx.measureText("max").width;
      ctx.font = "15px Georgia, serif";
      ctx.strokeText(" = 217 nm", ax + wL + wM, ay); ctx.fillText(" = 217 nm", ax + wL + wM, ay);
      ctx.restore();

      // marker readout: placed on the OPPOSITE side (left) of the dot so it can
      // never collide with the right-anchored λ_max label at the crest.
      var mx = xs.getPixelForValue(state.wl), my = ys.getPixelForValue(state.cur);
      var label = "A = " + state.cur.toFixed(2);
      ctx.save();
      ctx.font = "bold 12px sans-serif";
      var tw = ctx.measureText(label).width;
      ctx.restore();
      var placeLeft = (mx - 10 - tw) > (ca.left + 2);
      var rx = placeLeft ? (mx - 10) : (mx + 10);
      var ry = my + 4;
      if (ry > ca.bottom - 6) ry = my - 12;
      if (ry < ca.top + 12) ry = my + 18;
      haloText(ctx, label, rx, ry, "bold 12px sans-serif", "#111", placeLeft ? "right" : "left");
    },
    afterDraw: function (chart) {
      var ca = chart.chartArea; if (!ca) return;
      var ctx = chart.ctx;
      // X axis title + magenta rightward arrow
      var cx = (ca.left + ca.right) / 2, ty = ca.bottom + 26;
      ctx.save();
      ctx.font = "13px sans-serif"; ctx.fillStyle = "#000"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText("Wavelength (nm)", cx, ty);
      var tw = ctx.measureText("Wavelength (nm)").width;
      ctx.restore();
      arrow(ctx, cx + tw / 2 + 8, ty, cx + tw / 2 + 46, ty, MAGENTA, 2);
      // Y axis title (rotated) + magenta upward arrow
      var ycx = ca.left - 30, ycy = (ca.top + ca.bottom) / 2;
      ctx.save();
      ctx.translate(ycx, ycy); ctx.rotate(-Math.PI / 2);
      ctx.font = "13px sans-serif"; ctx.fillStyle = "#000"; ctx.textAlign = "center"; ctx.textBaseline = "middle";
      ctx.fillText("Absorbance", 0, 0);
      ctx.restore();
      arrow(ctx, ca.left - 44, ycy + 34, ca.left - 44, ycy - 34, MAGENTA, 2);
    }
  };

  var chart = new Chart(canvas, {
    type: "line",
    data: {
      datasets: [
        { data: curvePts, borderColor: MAGENTA, borderWidth: 2.5, pointRadius: 0, tension: 0, order: 2 },
        { data: [{ x: 217, y: cr(217) }], showLine: false, pointRadius: 5,
          pointBackgroundColor: MAGENTA, pointBorderColor: "#fff", pointBorderWidth: 1.5, order: 1 }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false, animation: false,
      layout: { padding: { left: 50, right: 18, top: 18, bottom: 38 } },
      scales: {
        x: { type: "linear", min: 200, max: 400,
          ticks: { stepSize: 20, color: "#000", font: { size: 12 } },
          grid: { display: false }, border: { color: "#000", width: 1 } },
        y: { type: "linear", min: 0, max: 1,
          ticks: { stepSize: 0.2, color: "#000", font: { size: 12 },
            callback: function (v) { return v.toFixed(1); } },
          grid: { display: false }, border: { color: "#000", width: 1 } }
      },
      plugins: { legend: { display: false }, tooltip: { enabled: false } }
    },
    plugins: [figurePlugin]
  });
  window.__markRendered();

  // ── Interaction handlers ──
  window.update_wavelengthScrub = function (v) {
    v = Math.max(200, Math.min(400, +v || 200));
    state.wl = v; state.cur = cr(v);
    chart.data.datasets[1].data = [{ x: v, y: state.cur }];
    var out = document.getElementById("wavelengthScrubVal"); if (out) out.value = v;
    chart.update("none");
  };
  window.update_regionEmphasis = function (val) {
    state.region = (val === "Highlight tail") ? "tail" : (val === "Highlight peak") ? "peak" : "none";
    chart.update("none");
  };

  // ── Demo step player ──
  var steps = [
    { title: "Read the spectrum",
      narration: "The magenta trace shows one sharp crest near 217 nm and a long, nearly flat tail beyond 250 nm; the annotation marks this crest as λ_max, the wavelength of maximum absorbance.",
      state: { wavelengthScrub: 217, regionEmphasis: "None" } },
    { title: "Scrub away from the peak",
      narration: "Drag the wavelength slider into the tail (e.g. 300 nm): the marker dot drops to the floor and the absorbance readout falls to near zero, showing how little light is absorbed far from λ_max.",
      state: { wavelengthScrub: 300, regionEmphasis: "None" } },
    { title: "Peak versus tail",
      narration: "Select 'Highlight tail' to shade the flat >250 nm region (then try 'Highlight peak'): the contrast makes clear that the diene's entire diagnostic absorption lives in the narrow short-wavelength maximum.",
      state: { wavelengthScrub: 217, regionEmphasis: "Highlight tail" } }
  ];
  var curStep = 0;

  function setRadio(val) {
    var ids = ["regionEmphasisInput", "regionEmphasisInput2", "regionEmphasisInput3"];
    var vals = ["None", "Highlight peak", "Highlight tail"];
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (el) el.checked = (vals[i] === val);
    }
  }

  function applyStep(i) {
    curStep = Math.max(0, Math.min(steps.length - 1, i));
    var s = steps[curStep];
    var sl = document.getElementById("wavelengthScrubInput");
    sl.value = s.state.wavelengthScrub;
    window.update_wavelengthScrub(s.state.wavelengthScrub);
    setRadio(s.state.regionEmphasis);
    window.update_regionEmphasis(s.state.regionEmphasis);
    document.getElementById("demoNarration").textContent = s.narration;
    document.getElementById("stepLabel").textContent = (curStep + 1) + " / " + steps.length;
  }
  window.nextStep = function () { applyStep(curStep + 1); };
  window.prevStep = function () { applyStep(curStep - 1); };

  applyStep(0);
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: The UV absorption spectrum of a conjugated diene like 1,3-butadiene is dominated by a single sharp peak at lambda_max (217 nm), with negligible absorbance across the long-wavelength tail, so lambda_max marks the wavelength of strongest absorption.
KEY INSIGHT (what students should walk away understanding): lambda_max is simply the wavelength where the absorbance curve reaches its single highest point, and for a simple conjugated diene that diagnostic absorption is confined to one sharp short-wavelength peak with a featureless tail elsewhere.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The UV absorption spectrum of a conjugated diene like 1,3-butadiene is dominated by a single sharp peak at lambda_max (217 nm), with negligible absorbance across the long-wavelength tail, so lambda_max marks the wavelength of strongest absorption.",
  "figureType": "line_plot",
  "elements": [
    "x-axis labeled 'Wavelength (nm)' spanning 200 to 400 with labeled ticks every 20 nm and a magenta rightward arrow after the label",
    "y-axis labeled 'Absorbance' spanning 0 to 1.0 with labeled ticks every 0.2 and a magenta upward arrow beside the label",
    "single magenta absorbance curve: enters near 0.34 at 200 nm, rises steeply to a rounded maximum just under 0.9 at ~217 nm, falls sharply to ~0.07 by 240 nm, then declines along a near-horizontal tail to ~0.03 at 400 nm",
    "annotation 'lambda_max = 217 nm' placed just above and right of the curve's crest",
    "soft pink vertical gradient background filling the plot area (deeper pink at top, fading toward the baseline)",
    "movable marker dot that rides the magenta curve at the slider's wavelength",
    "live numeric readout showing the absorbance value at the marker dot's wavelength"
  ],
  "interactions": [
    {
      "id": "wavelengthScrub",
      "type": "slider",
      "label": "Wavelength (nm)",
      "range": [
        200,
        400,
        1
      ],
      "default": 300,
      "teaches": "Scrubbing the wavelength moves a dot along the curve and updates the absorbance readout, revealing that absorbance climbs to its single highest value at 217 nm (lambda_max) and is nearly zero everywhere in the long-wavelength tail"
